#!/usr/bin/env python3
"""Patches the Android project generated by `flutter create` for WPDF."""
import glob
import os
import re
import shutil
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ANDROID = os.path.join(ROOT, "android")
APP = os.path.join(ANDROID, "app")
MAIN = os.path.join(APP, "src", "main")


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s):
    with open(p, "w", encoding="utf-8") as f:
        f.write(s)


def patch_manifest():
    p = os.path.join(MAIN, "AndroidManifest.xml")
    s = read(p)

    perms = [
        "android.permission.READ_EXTERNAL_STORAGE",
        "android.permission.WRITE_EXTERNAL_STORAGE",
        "android.permission.INTERNET",
    ]
    add = ""
    for perm in perms:
        if perm not in s:
            add += f'    <uses-permission android:name="{perm}"/>\n'
    s = s.replace("<application", add + "    <application", 1)

    s = re.sub(r'android:label="[^"]*"', 'android:label="WPDF"', s, count=1)
    if "android:requestLegacyExternalStorage" not in s:
        s = s.replace("<application", '<application android:requestLegacyExternalStorage="true"', 1)

    # Open PDF files from other apps / file managers.
    intent = """
            <intent-filter>
                <action android:name="android.intent.action.VIEW"/>
                <category android:name="android.intent.category.DEFAULT"/>
                <category android:name="android.intent.category.BROWSABLE"/>
                <data android:mimeType="application/pdf"/>
                <data android:scheme="content"/>
                <data android:scheme="file"/>
            </intent-filter>
"""
    if "application/pdf" not in s:
        s = s.replace("</activity>", intent + "        </activity>", 1)
    write(p, s)


def patch_gradle():
    done = False
    for name in ("build.gradle.kts", "build.gradle"):
        p = os.path.join(APP, name)
        if not os.path.exists(p):
            continue
        s = read(p)
        s2 = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 24", s)
        s2 = re.sub(r"minSdkVersion\s*=?\s*flutter\.minSdkVersion", "minSdkVersion 24", s2)
        s2 = re.sub(r"minSdk\s*=\s*\d+", "minSdk = 24", s2) if name.endswith(".kts") else s2
        write(p, s2)
        done = True
        print("patched", name)
    if not done:
        sys.exit("no app gradle file found")


def add_tesseract():
    dep_kts = '\ndependencies {\n    implementation("cz.adaptech.tesseract4android:tesseract4android:4.9.0")\n}\n'
    dep_groovy = "\ndependencies {\n    implementation 'cz.adaptech.tesseract4android:tesseract4android:4.9.0'\n}\n"
    for name, dep in (("build.gradle.kts", dep_kts), ("build.gradle", dep_groovy)):
        pth = os.path.join(APP, name)
        if os.path.exists(pth):
            s = read(pth)
            if "tesseract4android" not in s:
                write(pth, s + dep)
            print("tesseract dependency added to", name)
    # Tesseract4Android is published on JitPack: add the repository everywhere.
    root_kts = os.path.join(ANDROID, "build.gradle.kts")
    root_groovy = os.path.join(ANDROID, "build.gradle")
    if os.path.exists(root_kts):
        t = read(root_kts)
        if "jitpack.io" not in t:
            write(root_kts, t + '\nallprojects {\n    repositories {\n        maven { url = uri("https://jitpack.io") }\n    }\n}\n')
    elif os.path.exists(root_groovy):
        t = read(root_groovy)
        if "jitpack.io" not in t:
            write(root_groovy, t + "\nallprojects {\n    repositories {\n        maven { url 'https://jitpack.io' }\n    }\n}\n")
    for name in ("settings.gradle.kts", "settings.gradle"):
        sp = os.path.join(ANDROID, name)
        if os.path.exists(sp):
            t = read(sp)
            if "dependencyResolutionManagement" not in t and "jitpack.io" not in t:
                if name.endswith(".kts"):
                    t += '\ndependencyResolutionManagement {\n    repositories {\n        google()\n        mavenCentral()\n        maven { url = uri("https://jitpack.io") }\n    }\n}\n'
                else:
                    t += "\ndependencyResolutionManagement {\n    repositories {\n        google()\n        mavenCentral()\n        maven { url 'https://jitpack.io' }\n    }\n}\n"
                write(sp, t)
    # Replace MainActivity with the OCR bridge.
    kdir = os.path.join(MAIN, "kotlin")
    for old in glob.glob(os.path.join(kdir, "**", "MainActivity.*"), recursive=True):
        os.remove(old)
    for old in glob.glob(os.path.join(MAIN, "java", "**", "MainActivity.*"), recursive=True):
        os.remove(old)
    target = os.path.join(kdir, "com", "wpdf", "wpdf")
    os.makedirs(target, exist_ok=True)
    shutil.copy(os.path.join(ROOT, "tools", "MainActivity.kt"), os.path.join(target, "MainActivity.kt"))
    print("MainActivity installed")


def copy_icons():
    src = os.path.join(ROOT, "tools", "res")
    dst = os.path.join(MAIN, "res")
    for path in glob.glob(os.path.join(src, "**", "*"), recursive=True):
        if os.path.isdir(path):
            continue
        rel = os.path.relpath(path, src)
        out = os.path.join(dst, rel)
        os.makedirs(os.path.dirname(out), exist_ok=True)
        shutil.copy(path, out)
    print("icons copied")


if __name__ == "__main__":
    if not os.path.isdir(ANDROID):
        sys.exit("android/ not found - run flutter create first")
    patch_manifest()
    patch_gradle()
    add_tesseract()
    copy_icons()
    print("android patched")
